/** Generated by scripts/blog-plugin.mjs from src/content/blog/*.md */
declare module 'virtual:blog' {
  export interface PostMeta {
    slug: string
    title: string
    description: string
    category: string
    /** ISO date, YYYY-MM-DD. */
    date: string
    updated?: string
    tags: string[]
    /** Real photo for this article, if one exists in public/images/blog. */
    image?: string
    imageAlt?: string
    wordCount: number
    readingMinutes: number
  }
  
  export interface PostBody {
    html: string
    toc: { id: string; text: string }[]
    keyTakeaways: string[]
    faq: { q: string; a: string }[]
  }

  export const POSTS: PostMeta[]
}

declare module '*.md' {
  const body: import('virtual:blog').PostBody
  export default body
}
